ight:1.55;margin:0}.land-footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #303747;padding:12px 17px;font:9px var(--mono);color:var(--muted)}.gate-dots{display:flex;gap:4px}.gate-dot{width:9px;height:9px;border-radius:50%;background:#3a4352}.gate-dot.done{background:var(--lime)}.gate-dot.next{background:var(--pink);box-shadow:0 0 8px #ff789c70}.land-expand{border:0;background:none;color:var(--lime);font:10px var(--mono);padding:0}.land-details{padding:16px 17px;background:#11151e;border-top:1px solid var(--line);display:none}.land-card.expanded .land-details{display:block}.detail-columns{display:grid;grid-template-columns:1fr 1fr;gap:15px}.gate-list{display:grid;gap:5px}.gate-row{display:grid;grid-template-columns:20px 1fr auto;align-items:center;gap:8px;background:#191e2a;padding:7px 8px;font-size:10px}.gate-row .gate-num{font:9px var(--mono);color:var(--lime)}.gate-state{font:8px var(--mono);color:var(--faint)}.gate-state.completed{color:var(--lime)}.gate-state.available{color:var(--pink)}.npc-list{display:grid;gap:6px}.npc{font-size:10px;color:var(--muted)}.npc b{color:var(--text);font:10px var(--sans)}.entry-layout{display:grid;grid-template-columns:1fr 310px;gap:16px}.entry-list{display:grid;gap:8px}.entry-row{display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:14px;padding:13px;background:#11151e;border:1px solid #303747}.entry-num{font:17px var(--mono);color:var(--lime)}.entry-row b{font-size:12px}.entry-row small{display:block;color:var(--muted);font-size:10px;margin-top:4px}.entry-state{font:9px var(--mono);color:var(--faint)}.entry-state.complete{color:var(--lime)}.entry-side{display:flex;flex-direction:column;gap:12px}.checklist{display:grid;gap:9px}.check-item{display:flex;gap:9px;align-items:flex-start;color:#bdc3cf;font-size:10px;line-height:1.5}.check-item i{font-style:normal;color:var(--lime)}.action-button{width:100%;background:#252d3b;border:1px solid #3c4659;color:var(--text);padding:11px