(() => {
'use strict';
const CLASSES = [
 ['Heir','A figure who inherits, embodies, or is changed by a force.'],['Seer','A guide who learns to perceive patterns and possible paths.'],['Knight','A defender or resourceful combatant associated with a cause.'],['Page','A late-blooming figure with room to grow into a role.'],['Mage','One who learns through direct, often difficult experience.'],['Rogue','A redistribution-focused figure who moves a quality between others.'],['Thief','A figure who takes or claims a quality for themself.'],['Prince','A destructive or severing relationship with a quality.'],['Bard','A disruptive relationship through which a quality may be destroyed.'],['Maid','A figure who creates, maintains, or becomes associated with a quality.'],['Sylph','A restorative or nurturing relationship with a quality.'],['Witch','A figure who manipulates or bends a quality’s rules.']
