function networkHtml(){const order=topologicalOrder(session.players)||session.players.map(p=>p.id),n=order.length;const positions={};order.forEach((id,i)=>{const a=-Math.PI/2+2*Math.PI*i/n;positions[id]={x:50+34*Math.cos(a),y:50+34*Math.sin(a)}});const edges=session.players.filter(p=>p.serverId).map(p=>{let a=positions[p.serverId],b=positions[p.id];return `<line class="network-edge" x1="${a.x}%" y1="${a.y}%" x2="${b.x}%" y2="${b.y}%"/>`}).join('');return `<div class="network-layout"><div class="panel network-graph"><div class="panel-title"><span>DIRECTED SERVER NETWORK</span><em>ACYCLIC / VALID</em></div><svg class="network-svg" viewBox="0 0 100 100" preserveAspectRatio="none">${edges}</svg>${order.map((id,i)=>{const p=playerBy(id),pos=positions[id];return `<div class="network-node ${p.id===session.initialHostId?'host':''}" style="left:${pos.x}%;top:${pos.y}%"><span class="node-order">ENTRY ${String(p.entryOrder).padStart(2,'0')}${p.id===session.initialHostId?' · HOST':''}</span><b>${esc(p.name)}</b><small>${p.serverId?`← ${esc(playerBy(p.serverId).name)}`:'HOST'}</small></div>`}).join('')}</div><aside class="network-aside"><div class="panel"><div class="panel-title"><span>ROUTE EDITOR</span><em>LIVE</em></div><p class="network-help">A client enters after their server. Change a link to explore another valid chain. Cycles are rejected; one initial host is required.</p><div class="connection-editor">${session.players.map(p=>`<div class="connection-row"><label>${esc(p.name)} — server<select data-server-for="${p.id}"><option value="">No server · initial host</option>${session.players.filter(x=>x.id!==p.id).map(x=>`<option value="${x.id}" ${p.serverId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div>`).join('')}</div></div><div class="panel"><div class="panel-title"><span>ENTRY ORDER</span></div><div class="checklist">${order.map(id=>{const p=playerBy(id);return `<div class="check-item"><i>${p.entryOrder<10?'0'+p.entryOrder:p.entryOrder}</i><span><b>${esc(p.name)}</b>${p.serverId?` depends on ${esc(playerBy(p.serverId).name)}`:' is initial host'}</span></div>`}).join('')}</div><p class="note" style="margin-top:14px">Directed links represent server assistance. A player can be both client and server.</p></div></aside></div>`}

function validateSession(s){const errors=[];const ids=new Set(s.players.map(p=>p.id));if(ids.size!==s.players.length)errors.push('Player IDs are not unique.');for(const p of s.players){if(!CLASSES.some(c=>c.id===p.classId)||!ASPECTS.some(a=>a.id===p.aspectId))errors.push(`${p.name} has an invalid Classpect.`);if(!s.lands.some(l=>l.ownerId===p.id)||!s.sprites.some(x=>x.ownerId===p.id))errors.push(`${p.name} is missing a Land or Kernelsprite.`);if(p.serverId===p.id)errors.push(`${p.name} cannot be their own server.`)}for(const l of s.lands){if(l.gates.length!==7)errors.push(`${l.name} must have seven Gates.`);if(!l.consorts||!l.denizen)errors.push(`${l.name} is missing Land data.`)}if(s.connections.some(c=>!ids.has(c.serverId)||!ids.has(c.clientId)||c.serverId===c.clientId))errors.push('The server network contains an invalid reference.');if(!topologicalOrder(s.players))errors.push('The server network contains a dependency cycle.');if(errors.length){s.warnings=[...s.warnings,...errors];$('#tabContent').innerHTML=`<div class="panel"><h3>Session validation failed</h3>${errors.map(e=>`<p>${esc(e)}</p>`).join('')}<button class="button primary" onclick="document.querySelector('#newBtn').click()">Start over</button></div>`;throw new Error(errors.join(' '))}return true}
function topologicalOrder(players){const indeg=Object.fromEntries(players.map(p=>[p.id,p.serverId?1:0])),ready=players.filter(p=>!p.serverId).map(p=>p.id),out=[];while(ready.length){const id=ready.shift();out.push(id);for(const p of players)if(p.serverId===id){indeg[p.id]--;if(indeg[p.id]===0)ready.push(p.id)}}return out.length===players.length?out:null}
function showSession(){activeTab='overview';show('session');$('#headerStatus').textContent='SESSION ACTIVE';renderSession()}
function playerBy(id){return session.players.find(p=>p.id===id)}function landByOwner(id){return session.lands.find(l=>l.ownerId===id)}function spriteByOwner(id){return session.sprites.find(x=>x.ownerId===id)}
function renderSession(){if(!session)return;$('#sessionTitle').textContent=session.name;$('#sessionModeLabel').textContent=`/ ${session.mode.toUpperCase()}`;$('#sessionMeta').textContent=`SEED ${session.seed}  ·  ${session.settings.playerCount} PLAYERS  ·  ${session.settings.tone.toUpperCase()}  ·  ${session.settings.difficulty.toUpperCase()}`;$('#playerTabCount').textContent=session.players.length;$$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===activeTab));renderTab()}
function renderTab(){const root=$('#tabContent');switch(activeTab){case'overview':root.innerHTML=overviewHtml();break;case'players':root.innerHTML=playersHtml();break;case'network':root.innerHTML=networkHtml();break;case'lands':root.innerHTML=landsHtml();break;case'entry':root.innerHTML=entryHtml();break;case'reference':root.innerHTML=referenceHtml();break}bindTabEvents()}
function playerCard(p,compact=false){const i=session.players.indexOf(p),server=p.serverId?playerBy(p.serverId):null;return `<article class="player-card" style="--accent:${PALETTE[i%PALETTE.length]}"><div class="player-top"><span class="player-index">PLAYER ${String(i+1).padStart(2,'0')} · ENTRY ${p.entryOrder}</span><span class="moon-pill">${p.dreamMoon.toUpperCase()}</span></div><div class="player-name">${esc(p.name)}</div><div class="player-title">${esc(p.title)}</div><div class="player-links">${server?`SERVER: <span class="player-link" data-player="${server.id}">${esc(server.name)}</span>`:'INITIAL HOST'}${p.clientIds.length?` &nbsp;·&nbsp; CLIENTS: ${p.clientIds.map(id=>`<span class="player-link" data-player="${id}">${esc(playerBy(id).name)}</span>`).join(', ')}`:''}</div>${compact?'':`<div class="player-links">LAND: ${esc(landByOwner(p.id).name)}</div>`}</article>`}
function overviewHtml(){const host=playerBy(session.initialHostId),allEntered=session.players.filter(p=>session.entryState[p.id].entered).length;return `<div class="overview-grid"><div><div class="panel"><div class="panel-title"><span>SESSION ROSTER</span><em>${session.players.length} ACTIVE</em></div><div class="player-grid">${session.players.map(p=>playerCard(p,true)).join('')}</div></div><div class="world-banner"><div><div class="eyebrow">SHARED FIELD / BATTLEFIELD</div><h3>${session.battlefield.state}</h3><p>${session.battlefield.notes}</p></div><div class="world-icon">◈</div></div></div><aside class="summary-side"><div class="panel"><div class="panel-title"><span>SESSION READOUT</span><em>LIVE</em></div><div class="metric-grid"><div class="metric"><b>${allEntered}/${session.players.length}</b><small>PLAYERS ENTERED</small></div><div class="metric"><b>${session.lands.length}</b><small>LANDS MAPPED</small></div><div class="metric"><b>${session.connections.length}</b><small>SERVER LINKS</small></div><div class="metric"><b>${session.globalEvents.length}</b><small>COMPLICATIONS</small></div></div></div><div class="panel"><div class="panel-title"><span>INITIAL HOST</span><em>ENTRY 01</em></div><div class="player-name">${esc(host.name)}</div><div class="player-title">${esc(host.title)}</div><p class="note">${esc(host.name)} begins the installation process. Each client’s entry follows their server’s deployment.</p><button class="action-button" data-goto="network">Inspect server network ↗</button></div>${session.warnings.length?`<div class="alert-box"><b>SESSION NOTES</b>${session.warnings.slice(0,3).map(esc).join('<br>')}</div>`:''}</aside></div>`}
function playersHtml(){return `<div class="panel"><div class="panel-title"><span>PLAYER FILES / CLASSPECT REGISTER</span><em>${session.players.length} RECORDS</em></div><div class="player-grid">${session.players.map(p=>playerCard(p)).join('')}</div></div><div class="reference-grid" style="margin-top:14px">${session.players.map(p=>{const s=spriteByOwner(p.id);return `<article class="reference-card"><div class="tag">KERNELSPRITE · ${esc(p.id.toUpperCase())}</div><h3>${esc(p.name)}’s ${esc(p.title)}</h3><p>${esc(s.description)}<br><br><b>First prototype:</b> ${esc(s.prototyping[0].input)} (${s.prototyping[0].timing}).<br><b>Second imprint:</b> ${esc(s.prototyping[1].input)} (${s.prototyping[1].timing}).<br><b>Result:</b> ${esc(s.result)}<br><b>Persistent tags:</b> ${s.tags.map(esc).join(', ')}.</p><button class="action-button prototype-button" data-owner="${p.id}" ${session.entryState[p.id].entered?'':'disabled'}>${session.entryState[p.id].entered?'Apply post-entry imprint':'Post-entry imprint · enter first'}</button></article>`}).join('')}</div>`}
function networkHtml(){const order=topologicalOrder(session.players)||session.players.map(p=>p.id),n=order.length;const positions={};order.forEach((id,i)=>{const a=-Math.PI/2+2*Math.PI*i/n;positions[id]={x:50+34*Math.cos(a),y:50+34*Math.sin(a)}});const edges=session.players.filter(p=>p.serverId).map(p=>{let a=positions[p.serverId],b=positions[p.id];return `<line class="network-edge" x1="${a.x}%" y1="${a.y}%" x2="${b.x}%" y2="${b.y}%"/>`}).join('');return `<div class="network-layout"><div class="panel network-graph"><div class="panel-title"><span>DIRECTED SERVER NETWORK</span><em>ACYCLIC / VALID</em></div><svg class="network-svg" viewBox="0 0 100 100" preserveAspectRatio="none">${edges}</svg>${order.map(id=>{const p=playerBy(id),pos=positions[id];return `<div class="network-node ${p.id===session.initialHostId?'host':''}" style="left:${pos.x}%;top:${pos.y}%"><span class="node-order">ENTRY ${String(p.entryOrder).padStart(2,'0')}${p.id===session.initialHostId?' · HOST':''}</span><b>${esc(p.name)}</b><small>${p.serverId?`← ${esc(playerBy(p.serverId).name)}`:'HOST'}</small></div>`}).join('')}</div><aside class="network-aside"><div class="panel"><div class="panel-title"><span>ROUTE EDITOR</span><em>LIVE</em></div><p class="network-help">A client enters after their server. Change a link to explore another valid chain. Cycles are rejected; one initial host is required.</p><div class="connection-editor">${session.players.map(p=>`<div class="connection-row"><label>${esc(p.name)} — server<select data-server-for="${p.id}"><option value="">No server · initial host</option>${session.players.filter(x=>x.id!==p.id).map(x=>`<option value="${x.id}" ${p.serverId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div>`).join('')}</div></div><div class="panel"><div class="panel-title"><span>ENTRY ORDER</span></div><div class="checklist">${order.map(id=>{const p=playerBy(id);return `<div class="check-item"><i>${p.entryOrder<10?'0'+p.entryOrder:p.entryOrder}</i><span><b>${esc(p.name)}</b>${p.serverId?` depends on ${esc(playerBy(p.serverId).name)}`:' is initial host'}</span></div>`}).join('')}</div><p class="note" style="margin-top:14px">Directed links represent server assistance. A player can be both client and server.</p></div></aside></div>`}

function landsHtml(){return `<div class="panel-title"><span>LANDS OF THE MEDIUM</span><em>${session.lands.length} WORLDS · 7 GATES EACH</em></div><div class="land-grid">${session.lands.map(l=>{const p=playerBy(l.ownerId),done=l.gates.filter(g=>g.status==='completed').length,next=l.gates.find(g=>g.status!=='completed');return `<article class="land-card" data-land-card="${l.id}"><div class="land-card-head"><div class="land-owner">${esc(p.name.toUpperCase())} · ${esc(p.title.toUpperCase())}</div><h3>${esc(l.name)}</h3><div class="land-biome">${esc(l.environment)} / ${esc(l.secondaryEnvironment)}</div></div><div class="land-body"><div class="land-section"><b>THE PROBLEM</b><p>${esc(l.problem)} — ${esc(l.cause)}.</p></div><div class="land-section"><b>MAIN QUEST</b><p>${esc(l.quest.main)}</p></div><div class="land-section"><b>CONSORTS · ${esc(l.consorts.species.toUpperCase())}</b><p>${esc(l.consorts.description)} ${esc(l.consorts.understanding)}</p></div><div class="land-section"><b>DENIZEN · ${esc(l.denizen.name.toUpperCase())}</b><p>${esc(l.denizen.archetype)} — ${esc(l.denizen.challenge)}.</p></div></div><div class="land-footer"><div class="gate-dots" title="${done} of 7 gates complete">${l.gates.map((g,i)=>`<span class="gate-dot ${g.status==='completed'?'done':g.status==='unlocked'?'next':''}"></span>`).join('')}</div><span>GATES ${done}/7</span><button class="land-expand" data-expand="${l.id}">DETAILS +</button></div><div class="land-details"><div class="detail-columns"><div><div class="land-section"><b>QUEST RATIONALE</b><p>${esc(l.quest.rationale)}</p></div><div class="land-section"><b>GEOGRAPHY & LANDMARKS</b><p>${esc(l.geography)} Landmarks: ${l.landmarks.map(esc).join(' · ')}.</p></div><div class="land-section"><b>CONSORT SOCIETY</b><p>${esc(l.consorts.customs)} ${esc(l.consorts.understanding)}</p></div><div class="land-section"><b>DENIZEN DOMAIN / OUTCOMES</b><p>${esc(l.denizen.domain)}. ${esc(l.denizen.connection)} Possible outcomes: ${l.denizen.outcomes.map(esc).join(' · ')}. Reward: ${esc(l.denizen.reward)}</p></div></div><div><div class="land-section"><b>SEVEN GATES / IMPLEMENTATION ROUTE</b><div class="gate-list">${l.gates.map(g=>`<div class="gate-row"><span class="gate-num">${g.number}</span><span>${esc(g.location)} — ${esc(g.challenge)}</span><span class="gate-state ${g.status==='completed'?'completed':g.status==='unlocked'?'available':''}">${g.status.toUpperCase()}</span></div>`).join('')}</div></div><div class="land-section"><b>LOCAL NPCs</b><div class="npc-list">${l.consorts.npcs.map(n=>`<div class="npc"><b>${esc(n.name)} · ${esc(n.role)}</b> — ${esc(n.style)}. ${esc(n.knowledge)}</div>`).join('')}</div></div><div class="land-section"><b>BRANCHES / UNDERLINGS / RESOURCES</b><p>${l.quest.branches.map(esc).join(' ')} Enemy themes: ${l.enemies.map(esc).join(', ')}. ${esc(l.resources)}</p></div><div class="land-section"><b>GENERATION RATIONALE</b><p>${esc(l.generationRationale)}</p></div></div></div><button class="action-button gate-action" data-land="${l.id}" ${!session.entryState[p.id].entered||!next?'disabled':''}>${next?(session.entryState[p.id].entered?`Resolve Gate ${next.number}: ${esc(next.challenge)}`:'Enter the Medium to begin Land progression'):'All seven gates complete — Skaian approach reached'}</button></div></article>`}).join('')}</div>`}
const ENTRY_STEPS=[['machinery','Deploy Cruxtruder, Totem Lathe & Alchemiter'],['sprite','Create Kernelsprite'],['firstPrototype','Complete first prototyping'],['pattern','Receive artifact pattern'],['dowel','Carve Cruxite Dowel'],['artifact','Create Cruxite artifact'],['entered','Activate artifact · enter the Medium']];
function entryHtml(){const ordered=session.entryOrder.map(id=>playerBy(id)),done=ordered.filter(p=>session.entryState[p.id].entered).length;return `<div class="entry-layout"><div class="panel"><div class="panel-title"><span>ENTRY EVENT LOG</span><em>${done}/${ordered.length} ENTERED</em></div><div class="entry-list">${ordered.map(p=>{const st=session.entryState[p.id],first=ENTRY_STEPS.find(x=>!st[x[0]]);return `<div class="entry-row"><div class="entry-num">${String(p.entryOrder).padStart(2,'0')}</div><div><b>${esc(p.name)} · ${esc(p.title)}</b><small>${st.entered?'Entered the Medium':p.serverId?`Awaiting server deployment from ${esc(playerBy(p.serverId).name)}`:'Initial host'} · Meteor: ${esc(st.meteor)}</small></div><span class="entry-state ${st.entered?'complete':''}">${st.entered?'ENTERED':first?`STEP ${ENTRY_STEPS.indexOf(first)+1}/7`:'READY'}</span></div>`}).join('')}</div></div><aside class="entry-side"><div class="panel"><div class="panel-title"><span>NEXT ENTRY ACTION</span><em>IMPLEMENTATION</em></div><div class="checklist">${ordered.map(p=>{const st=session.entryState[p.id],first=ENTRY_STEPS.find(x=>!st[x[0]]);return `<div class="check-item"><i>${st.entered?'✓':String(p.entryOrder).padStart(2,'0')}</i><span><b>${esc(p.name)}</b> · ${first?esc(first[1]):'complete'}${first&&first[0]==='entered'?'<br>Be ready to activate the artifact.':''}</span></div>`}).join('')}</div><p class="note">The first player in the valid dependency order can proceed. A client cannot deploy required machinery until their server has entered.</p>${(()=>{const p=ordered.find(x=>!session.entryState[x.id].entered);if(!p)return `<div class="alert-box">ALL PLAYERS ENTERED. The Medium is live. Inspect the Lands tab to advance the seven-gate routes.</div>`;const st=session.entryState[p.id],step=ENTRY_STEPS.find(x=>!st[x[0]]);if(p.serverId&&!session.entryState[p.serverId].entered)return `<button class="action-button" disabled>Waiting for ${esc(playerBy(p.serverId).name)} to enter first</button>`;return `<button class="button primary" style="width:100%;margin-top:14px" data-entry-action="${p.id}">${esc(p.name)}: ${esc(step[1])} <span>↗</span></button>`})()}</div><div class="panel"><div class="panel-title"><span>SESSION CONSEQUENCES</span><em>SHARED STATE</em></div><p class="note">${esc(session.battlefield.notes)}</p><div class="land-section"><b>BATTLEFIELD TAGS</b><p class="note">${session.battlefield.tags.map(esc).join(' · ')}</p></div><div class="land-section"><b>ACTIVE SIGNALS</b><p class="note">${session.globalEvents.length?session.globalEvents.map(esc).join('<br>'): 'No additional complications enabled.'}</p></div></div></aside></div>`}
function referenceHtml(){return `<div class="reference-grid">${[['CANON ANCHOR','The comic establishes human SBURB machinery, prototyping, dream moons, Lands, Gates, and powerful Denizens. The entry sequence includes a Cruxtruder, Totem Lathe, Alchemiter, Kernelsprite, and Cruxite artifact.'],['INTERPRETATION','Class and Aspect descriptions are interpretive thematic guides. The comic does not provide a complete universal ability specification or a deterministic method for assigning every Title.'],['IMPLEMENTATION RULE','This recreation uses a seeded acyclic server network, seven generated Gate records, and descriptive rather than numerical progression. Difficulty labels and generated trials are local game rules.'],['PROTOTYPING','Prototype inputs create persistent tags and session-wide notes. The exact downstream effects are provisional implementation rules, not a complete simulation of royal powers or enemy changes.'],['DREAM SELVES','Prospit and Derse are the two dream moons. This generator tracks a separate dream-self status and location; dream exploration is not simulated.'],['SAVE & REPLAY','Save stores the complete generated session, including seed, configuration, current entry progress, and gate progress, in this browser. Export JSON to keep a portable copy.']].map(([tag,text])=>`<article class="reference-card"><div class="tag">${tag}</div><p>${text}</p></article>`).join('')}</div><div class="panel" style="margin-top:14px"><div class="panel-title"><span>GENERATION NOTES & VALIDATION</span><em>${session.warnings.length?'NOTES':'CLEAR'}</em></div>${session.warnings.length?`<div class="warning-list">${session.warnings.map(x=>`<div class="warning-row">${esc(x)}</div>`).join('')}</div>`:'<p class="note">The session passed structural validation: player references, Classpects, Lands, sprites, seven Gates, and the dependency graph are consistent.'}<p class="note">${session.generationLog.map(esc).join('<br>')}</p><button class="action-button" id="rerollBtn">Regenerate entire session with a fresh seed</button></div>`}

