function entryHtml(){const ordered=session.entryOrder.map(id=>playerBy(id)),done=ordered.filter(p=>session.entryState[p.id].entered).length;return `<div class="entry-layout"><div class="panel"><div class="panel-title"><span>ENTRY EVENT LOG</span><em>${done}/${ordered.length} ENTERED</em></div><div class="entry-list">${ordered.map(p=>{const st=session.entryState[p.id],first=ENTRY_STEPS.find(x=>!st[x[0]]);return `<div class="entry-row"><div class="entry-num">${String(p.entryOrder).padStart(2,'0')}</div><div><b>${esc(p.name)} · ${esc(p.title)}</b><small>${st.entered?'Entered the Medium':p.serverId?`Awaiting server deployment from ${esc(playerBy(p.serverId).name)}`:'Initial host'} · Meteor: ${esc(st.meteor)}</small></div><span class="entry-state ${st.entered?'complete':''}">${st.entered?'ENTERED':first?`STEP ${ENTRY_STEPS.indexOf(first)+1}/7`:'READY'}</span></div>`}).join('')}</div></div><aside class="entry-side"><div class="panel"><div class="panel-title"><span>NEXT ENTRY ACTION</span><em>IMPLEMENTATION</em></div><div class="checklist">${ordered.map(p=>{const st=session.entryState[p.id],first=ENTRY_STEPS.find(x=>!st[x[0]]);return `<div class="check-item"><i>${st.entered?'✓':String(p.entryOrder).padStart(2,'0')}</i><span><b>${esc(p.name)}</b> · ${first?esc(first[1]):'complete'}${first&&first[0]==='entered'?'<br>Be ready to activate the artifact.':''}</span></div>`}).join('')}</div><p class="note">The first player in the valid dependency order can proceed. A client cannot deploy required machinery until their server has entered.</p>${(()=>{const p=ordered.find(x=>!session.entryState[x.id].entered);if(!p)return `<div class="alert-box">ALL PLAYERS ENTERED. The Medium is live. Inspect the Lands tab to advance the seven-gate routes.</div>`;const st=session.entryState[p.id],step=ENTRY_STEPS.find(x=>!st[x[0]]);if(p.serverId&&!session.entryState[p.serverId].entered)return `<button class="action-button" disabled>Waiting for ${esc(playerBy(p.serverId).name)} to enter first</button>`;return `<button class="button primary" style="width:100%;margin-top:14px" data-entry-action="${p.id}">${esc(p.name)}: ${esc(step[1])} <span>↗</span></button>`})()}</div><div class="panel"><div class="panel-title"><span>SESSION CONSEQUENCES</span><em>SHARED STATE</em></div><p class="note">${esc(session.battlefield.notes)}</p><div class="land-section"><b>BATTLEFIELD TAGS</b><p class="note">${session.battlefield.tags.map(esc).join(' · ')}</p></div><div class="land-section"><b>ACTIVE SIGNALS</b><p class="note">${session.globalEvents.length?session.globalEvents.map(esc).join('<br>'): 'No additional complications enabled.'}</p></div></div></aside></div>`}
function referenceHtml(){return `<div class="reference-grid">${[['CANON ANCHOR','The comic establishes human SBURB machinery, prototyping, dream moons, Lands, Gates, and powerful Denizens. The entry sequence includes a Cruxtruder, Totem Lathe, Alchemiter, Kernelsprite, and Cruxite artifact.'],['INTERPRETATION','Class and Aspect descriptions are interpretive thematic guides. The comic does not provide a complete universal ability specification or a deterministic method for assigning every Title.'],['IMPLEMENTATION RULE','This recreation uses a seeded acyclic server network, seven generated Gate records, and descriptive rather than numerical progression. Difficulty labels and generated trials are local game rules.'],['PROTOTYPING','Prototype inputs create persistent tags and session-wide notes. The exact downstream effects are provisional implementation rules, not a complete simulation of royal powers or enemy changes.'],['DREAM SELVES','Prospit and Derse are the two dream moons. This generator tracks a separate dream-self status and location; dream exploration is not simulated.'],['SAVE & REPLAY','Save stores the complete generated session, including seed, configuration, current entry progress, and gate progress, in this browser. Export JSON to keep a portable copy.']].map(([tag,text])=>`<article class="reference-card"><div class="tag">${tag}</div><p>${text}</p></article>`).join('')}</div><div class="panel" style="margin-top:14px"><div class="panel-title"><span>GENERATION NOTES & VALIDATION</span><em>${session.warnings.length?'NOTES':'CLEAR'}</em></div>${session.warnings.length?`<div class="warning-list">${session.warnings.map(x=>`<div class="warning-row">${esc(x)}</div>`).join('')}</div>`:'<p class="note">The session passed structural validation: player references, Classpects, Lands, sprites, seven Gates, and the dependency graph are consistent.'}<p class="note">${session.generationLog.map(esc).join('<br>')}</p><button class="action-button" id="rerollBtn">Regenerate entire session with a fresh seed</button></div>`}

