(()=>{
'use strict';
const CLASSES=['Heir','Seer','Knight','Page','Mage','Rogue','Thief','Prince','Bard','Maid','Sylph','Witch'];
const ASPECTS=['Time','Space','Light','Void','Heart','Mind','Rage','Hope','Life','Doom','Breath','Blood'];
const ASPECTS_INFO={Time:'change, sequence, and endings',Space:'creation, distance, and form',Light:'knowledge, fortune, and attention',Void:'absence, secrecy, and the unknown',Heart:'identity, emotion, and the self',Mind:'choice, reason, and consequence',Rage:'conviction, fear, and intensity',Hope:'belief, possibility, and ideals',Life:'growth, vitality, and abundance',Doom:'limits, sacrifice, and obligation',Breath:'freedom, direction, and motion',Blood:'bonds, duty, and connection'};
const ENV=[['glass deserts','salt flats'],['moss forests','sunken valleys'],['storm coasts','tidal caverns'],['ash mountains','basalt fields'],['frozen wetlands','blue ice shelves'],['hanging gardens','root-choked ruins'],['chalk plateaus','wind-cut ravines'],['fungal groves','underground rivers'],['brass badlands','steam vents'],['cloud reefs','floating marshes']];
const MOTIFS={Time:['a procession of abandoned bells','a sequence of seasons trapped out of order','a city that forgets one hour each day'],Space:['a nesting set of impossible rooms','a scattered archipelago slowly drawing together','a vast orchard of miniature moons'],Light:['a lighthouse whose beam reveals buried roads','a market where every reflection shows a clue','a constellation projected beneath the soil'],Void:['a map with blank spaces that keep spreading','a library of books with missing middles','a silent district erased from every sign'],Heart:['masks that remember their former wearers','a theater whose roles change their actors','a chorus of statues with individual names'],Mind:['bridges that rearrange when choices are made','a maze of contradictory signposts','a courthouse where testimony changes the walls'],Rage:['a red quarry where old arguments echo','a fortress built around a sealed alarm','a carnival that turns anxieties into spectacles'],Hope:['a seed vault glowing under a dead plain','an unfinished tower visible from every shore','a lantern trail leading beyond the horizon'],Life:['a greenhouse growing through a city','a river carrying medicinal seeds upstream','a garden reclaiming a machine-age ruin'],Doom:['a dam holding back a slow black tide','a clockwork hospice for broken machines','a chain of shrines recording old debts'],Breath:['wind-carved bridges between drifting mesas','a fleet of kites tethering the clouds','a road that moves whenever no one watches'],Blood:['a network of villages linked by root bridges','a red river joining isolated settlements','a fortress whose doors open only for guests']};
const SPECIES=['marsh salamanders','copper-backed tortoises','glasswing moth-folk','burrowing newts','long-eared river drakes','moss-covered geckos','tiny horned badgers','reed-dwelling frogs','stone-shell armadillos','feathered lizards'];
const DENIZENS=['Echidna','Typheus','Cetus','Hephaestus'];
const LOCATIONS=['the Sunken Switchyard','the Cracked Observatory','the Amber Causeway','the Quiet Orchard','the Windward Steps','the Buried Amphitheater','the Saltglass Causeway'];
const PROTOTYPES=['a brass compass','a paper crown','a stubborn housecat','a cracked teacup','a toy airship','a bundle of keys','a moth-eaten banner','a pocket mirror','a wooden drum','a snow globe'];
const FIRST_NAMES=['Ari','Mina','Rowan','Jules','Niko','Tess','Remy','Sasha','Ira','Vale','Kit','Noor','Cleo','Ash','Rin','Morgan'];
const LAST_NAMES=['Bell','North','Wren','Morrow','Vale','Quill','Rook','Sable','Day','Finch','Marsh','Reed'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let session=null,activeTab='overview',toastTimer;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function hashSeed(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function rng(seed){let a=hashSeed(String(seed));return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function pick(r,a){return a[Math.floor(r()*a.length)]}
function shuffle(r,a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function titleCase(s){return s.replace(/\b\w/g,c=>c.toUpperCase())}
function idFor(seed,prefix,i){return `${prefix}-${hashSeed(seed).toString(36)}-${i+1}`}
function makeGuidedFields(){const count=+$('#playerCount').value,container=$('#guidedPlayers');const previous=[...container.querySelectorAll('.guided-player')].map(card=>Object.fromEntries([...card.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])));container.innerHTML=Array.from({length:count},(_,i)=>{const old=previous[i]||{},opts=(list,val,label)=>`<option value="">Random ${label}</option>${list.map(x=>`<option ${val===x?'selected':''}>${esc(x)}</option>`).join('')}`;return `<div class="guided-player"><div class="guided-player-title">PLAYER ${String(i+1).padStart(2,'0')}</div><label>Name<input data-field="name" maxlength="32" placeholder="Random name" value="${esc(old.name||'')}"></label><div class="field-row"><label>Class<select data-field="class">${opts(CLASSES,old.class,'Class')}</select></label><label>Aspect<select data-field="aspect">${opts(ASPECTS,old.aspect,'Aspect')}</select></label></div><div class="field-row"><label>Dream moon<select data-field="moon"><option value="">Random moon</option>${['Prospit','Derse'].map(x=>`<option ${old.moon===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Server<select data-field="server"><option value="">Random server / host</option>${Array.from({length:count},(_,j)=>j===i?'':`<option value="${j}" ${old.server===String(j)?'selected':''}>Player ${String(j+1).padStart(2,'0')}</option>`).join('')}</select></label></div></div>`}).join('');}
function guidedInputs(){return [...$('#guidedPlayers').querySelectorAll('.guided-player')].map(el=>Object.fromEntries([...el.querySelectorAll('[data-field]')].map(x=>[x.dataset.field,x.value.trim()])))}
function generate(config){const seed=config.seed||`SB-${Date.now().toString(36).toUpperCase()}`,r=rng(seed),n=+config.count,inputs=config.mode==='guided'?config.guided:[];const names=new Set(),titles=new Set();let order=shuffle(r,Array.from({length:n},(_,i)=>i));const rank=Object.fromEntries(order.map((v,i)=>[v,i]));
 const players=Array.from({length:n},(_,i)=>{let g=inputs[i]||{},name=g.name||`${pick(r,FIRST_NAMES)} ${pick(r,LAST_NAMES)}`;while(names.has(name))name+=` ${i+1}`;names.add(name);let cls=g.class||pick(r,CLASSES),aspect=g.aspect||pick(r,ASPECTS),title=`${cls} of ${aspect}`;if(config.uniqueTitles){let tries=0;while(titles.has(title)&&tries++<30){if(!g.class)cls=pick(r,CLASSES);if(!g.aspect)aspect=pick(r,ASPECTS);title=`${cls} of ${aspect}`}}titles.add(title);return{id:idFor(seed,'player',i),name,className:cls,aspect,title,dreamMoon:g.moon||pick(r,['Prospit','Derse']),serverIndex:g.server!==''&&g.server!==undefined?+g.server:null,entryOrder:0,serverId:null,clientIds:[],landId:idFor(seed,'land',i),spriteId:idFor(seed,'sprite',i),generationLog:[g.name?'Name fixed by creator':'Name generated',g.class||g.aspect?'Classpect partly constrained':'Classpect generated',g.moon?'Dream moon fixed by creator':'Dream moon generated']}});
 // Honor valid guided server choices. Automatic links always point from later to earlier entry.
 players.forEach((p,i)=>{if(p.serverIndex!==null&&p.serverIndex!==i&&rank[p.serverIndex]<rank[i])p.serverId=players[p.serverIndex].id;else if(i>0&&!(inputs[i]&&inputs[i].server!==''))p.serverId=players[order[Math.floor(r()*rank[i])]].id});
 const sorted=order.map(i=>players[i]);sorted.forEach((p,i)=>p.entryOrder=i+1);players.forEach(p=>{p.clientIds=[];if(p.serverId){let server=players.find(x=>x.id===p.serverId);server.clientIds.push(p.id)}});
 const sprites=players.map(p=>{let first=pick(r,PROTOTYPES),second=pick(r,PROTOTYPES),tags=[p.aspect.toLowerCase(),first.split(' ').pop().replace(/[.,]/g,'').toLowerCase(),second.split(' ').pop().replace(/[.,]/g,'').toLowerCase()];return{id:p.spriteId,ownerId:p.id,description:`A small guide with ${pick(r,['bright button eyes','a stitched smile','a paper-thin silhouette','a glassy halo'])} and a voice like ${pick(r,['distant radio','wind through a keyhole','a cheerful announcer','a careful whisper'])}.`,prototyping:[{input:first,timing:'pre-entry'},{input:second,timing:'planned second prototype'}],tags,effects:[`Sprite presentation reflects ${first} and ${second}.`,`Session tag: ${tags.join(', ')}.`]}});
 const lands=players.map((p,i)=>{let [environment,secondaryEnvironment]=pick(r,ENV),motif=pick(r,MOTIFS[p.aspect]),nounA=pick(r,['Lanterns','Echoes','Roots','Mirrors','Cinders','Tides','Bridges','Moths','Orchards','Signals','Riddles','Anchors']),nounB=titleCase(motif.split(' ').slice(-2).join(' '));const species=pick(r,SPECIES),problem=pick(r,['the channels have stopped carrying fresh water','a veil of drifting ash hides the safest roads','the settlement’s bells ring warnings no one understands','the old bridges are slowly turning toward the sea','a pale growth is consuming the shared seed stores','the valley’s paths rearrange after every storm']),cause=pick(r,['a damaged weather engine is repeating its last command','a forgotten bargain is being enforced by an ancient gate','the Denizen’s sealed domain is leaking into the surface','a buried machine has mistaken the settlement for an intruder','the Consorts’ old warning system has fallen out of balance']),denizen=pick(r,DENIZENS),landId=p.landId;const gates=Array.from({length:7},(_,j)=>({number:j+1,location:pick(r,LOCATIONS),requirement:j===0?'Reach the first landmark and learn the local route':`Resolve the previous Gate’s obstacle and earn the Consorts’ route token`,challenge:pick(r,['cross a shifting causeway','settle a dispute between rival guides','restore a broken signal','navigate a field of harmless but persistent underlings','recover a lost map fragment','answer a Denizen’s riddle','repair a stranded transport']),destination:j===6?'A route toward Skaia':`A deeper region of the Land`,status:j===0?'unlocked':'locked'}));return{id:landId,ownerId:p.id,name:`Land of ${nounA} and ${nounB}`,environment,secondaryEnvironment,geography:`${motif}; ${environment} meet ${secondaryEnvironment} around a central settlement.`,landmarks:[pick(r,LOCATIONS),pick(r,LOCATIONS)],problem,cause,quest:{main:`Help the ${species} restore the routes and resources disrupted by the Land’s central problem.`,rationale:`${p.aspect} themes of ${ASPECTS_INFO[p.aspect]} shape the clues and choices, while the local problem gives the quest a concrete purpose.`,branches:[`Find out why ${motif} began appearing near the settlement.`,`Help a neighboring group preserve its route to the central landmark.`]},consorts:{species,description:`A community of ${species} who build practical homes from local materials.`,settlement:`${pick(r,['Reedmarket','Low Lantern','Moss Crossing','Copper Nest','Stillwater','The Long Burrow'])}`,customs:`They ${pick(r,['leave a place at every meal for an absent traveler','trade stories before exchanging tools','mark safe paths with woven ribbons','hold a quiet vote whenever the bells sound'])}.`,understanding:`They believe ${cause}.`,npcs:[{name:`${pick(r,FIRST_NAMES)} ${pick(r,LAST_NAMES)}`,role:'route keeper',style:'direct and observant',knowledge:`knows how ${problem} began`,status:'available'},{name:`${pick(r,FIRST_NAMES)} ${pick(r,LAST_NAMES)}`,role:'seed archivist',style:'patient and precise',knowledge:'has records of an earlier warning',status:'available'},{name:`${pick(r,FIRST_NAMES)} ${pick(r,LAST_NAMES)}`,role:'young courier',style:'curious and quick',knowledge:'can reveal a safe side route',status:'available'}]},denizen:{name:denizen,archetype:`a powerful entity with a domain beneath ${environment}`,domain:pick(r,['the drowned observatory','a furnace-temple','a chamber of roots','the silent tide vault']),temperament:pick(r,['cryptic but attentive','impatient with evasions','curious about mortal choices','solemn and transactional']),challenge:`${pick(r,['offer a meaningful sacrifice','choose which route to preserve','prove the value of an imperfect promise','negotiate a change to the old bargain'])} connected to ${p.aspect.toLowerCase()} and the Land’s crisis`,connection:`Its domain holds evidence about ${cause}.`,outcomes:['a bargain that changes the Land','a test that grants a progression clue','a confrontation that opens the route'],reward:'A Denizen progression flag (descriptive; no combat stats).'},gates,resources:`Local grist is associated with ${pick(r,['route repair','glassworking','seed cultivation','signal relays'])}; no economy is simulated.`,enemies:[pick(r,['imp scouts','lost machine husks','ash moth swarms','unruly marsh beasts'])],generationRationale:`The ${p.title} receives a Land whose ${p.aspect} motifs influence its mystery without determining every detail.`}});

