function commitNetwork(){try{const links={};session.players.forEach(p=>{const el=$(`[data-server="${p.id}"]`);links[p.id]=el?el.value:(p.serverId||'')});const order=topoFor(links);session.players.forEach(p=>{p.serverId=links[p.id]||null;p.clientIds=[]});session.players.forEach(p=>{if(p.serverId)playerBy(p.serverId).clientIds.push(p.id)});session.connections=session.players.filter(p=>p.serverId).map(p=>({serverId:p.serverId,clientId:p.id}));session.entryOrder=order;session.players.forEach(p=>p.entryOrder=order.indexOf(p.id)+1);render();showToast('Network validated; entry order updated.')}catch(e){showToast(e.message)}}
