 function render(){if(!session)return;$('#welcome').classList.add('hidden');$('#setup').classList.add('hidden');$('#sessionView').classList.remove('hidden');$('#headerStatus').textContent='SESSION ACTIVE';$('#sessionTitle').textContent=session.name;$('#sessionModeLabel').textContent=`· ${session.mode.toUpperCase()}`;$('#sessionMeta').textContent=`${session.players.length} players · seed ${session.seed} · ${session.settings.difficulty} difficulty`;$('#playerTabCount').textContent=session.players.length;$$('#tabs .tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===activeTab));const views={overview:overviewHtml,players:playersHtml,network:networkHtml,lands:landsHtml,entry:entryHtml,reference:referenceHtml};$('#tabContent').innerHTML=views[activeTab]();}
