UTE</b><div class="gate-list">${l.gates.map(g=>`<div class="gate-row"><span class="gate-num">${g.number}</span><span>${esc(g.location)} — ${esc(g.requirement)}; ${esc(g.challenge)}. ${esc(g.destination)}</span><span class="gate-state ${g.status==='completed'?'completed':g.status==='unlocked'?'available':''}">${g.status.toUpperCase()}</span></div>`).join('')}</div></div><div class="land-section"><b>LOCAL NPCs</b><div class="npc-list">${l.consorts.npcs.map(n=>`<div class="npc"><b>${esc(n.name)} · ${esc(n.role)}</b> — ${esc(n.style)}. ${esc(n.knowledge)}. Status: ${esc(n.status)}.</div>`).join('')}</div></div><div class="land-section"><b>BRANCHES / UNDERLINGS / RESOURCES</b><p>${l.quest.branches.map(esc).join(' ')} Enemy themes: ${l.enemies.map(esc).join(', ')}. ${esc(l.resources)}</p></div><div class="land-section"><b>GENERATION RATIONALE</b><p>${esc(l.generationRationale)}</p></div></div></div><button class="action-button gate-action" data-land="${l.id}" ${!session.entryState[p.id].entered||!next?'disabled':''}>${next?(session.entryState[p.id].entered?`Resolve Gate ${next.number}: ${esc(next.challenge)}`:'Enter the Medium to begin Land progression'):'All seven gates complete — Skaian approach reached'}</button></div></article>`}).join('')}</div>`}
